mapper.select:
select `u`.`id`,`u`.`account`, `u`.`name`, `u`.`phone`, `u`.`status`, `u`.`create_time`, `d`.`name` as `dept_name`, `d`.`id` as `dept_id`
from sys_user as u
left join sys_dept as d on `d`.`id` = `u`.`dept_id`


        `u`.`name` like concat("%",#{dto.name},"%")


        and `u`.`phone` like concat("%",#{dto.phone},"%")


        and `u`.`status`=#{dto.status}


        and `u`.`status`=1


        and u.`dept_id`=#{dto.deptId}


        and `u`.`create_time` >= #{dto.beginTime}


        and `u`.`create_time` <= #{dto.endTime}

    and `u`.`deleted`=0

order by `u`.`create_time` desc

select `u`.`id`,`u`.`account`, `u`.`name`, `u`.`phone`, `u`.`status`, `u`.`create_time`, `d`.`name` as `dept_name`, `d`.`id` as `dept_id`
from sys_user as u
inner join sys_tenant_user as tu on `u`.`id` = `tu`.`user_id` and `tu`.`status` = 1
left join sys_dept as d on `d`.`id` = `u`.`dept_id`


        `u`.`name` like concat("%",#{dto.name},"%")


        and `u`.`phone` like concat("%",#{dto.phone},"%")


        and `u`.`status`=#{dto.status}


        and `u`.`status`=1


        and u.`dept_id`=#{dto.deptId}


        and `u`.`create_time` >= #{dto.beginTime}


        and `u`.`create_time` <= #{dto.endTime}

    and `u`.`deleted`=0

order by `u`.`create_time` desc

select t.id, t.name, t.phone, t.avatar from sys_user t


        and t.id in

            #{id}



        t.`name` like concat("%",#{name},"%")


        and t.`phone` like concat("%",#{phone},"%")


        and t.`status`=#{status}


        and t.`status`=1


        and t.`dept_id`=#{deptId}


        and t.`create_time` >= #{beginTime}


        and t.`create_time` <= #{endTime}

    and t.deleted = 0
